import { expect, test, uniqueName } from "../../fixtures";

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev Vendor"), category: "services", contact_email: "ap@rev-vendor.example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = (await created.json()).id as string;

  const docIds: Record<string, string> = {};
  for (const kind of ["w9", "insurance_certificate", "contract"]) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 test document") },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    docIds[kind] = (await upload.json()).id as string;
  }

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendorId}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  const extractionRes = await reviewer.get(`/api/documents/${docIds.w9}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extractionId = (await extractionRes.json()).id as string;

  const withoutNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject" },
  });
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);

  const withNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  expect(withNote.status(), await withNote.text()).toBe(200);

  await expect
    .poll(
      async () => {
        const res = await reviewer.get(`/api/vendors/${vendorId}`);
        return ((await res.json()) as { status: string }).status;
      },
      { timeout: 30_000 },
    )
    .toBe("rejected");

  await expect
    .poll(
      async () => {
        const res = await reviewer.get(`/api/vendors/${vendorId}/audit`);
        const trail = (await res.json()) as { items: { action: string }[] };
        return trail.items.some((e) => e.action === "extraction.rejected");
      },
      { timeout: 30_000 },
    )
    .toBe(true);
});
